// TypeScript Version: 4.1

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the routine completed successfully.
* -   if greater than zero, then overflow would occur when computing the `k`-th element of the solution vector `x`, where `k = StatusCode`. This can only occur when `job` is supplied as positive and either means that a diagonal element of `U` is very small, or that the elements of the right-hand side vector `y` are very large.
*/
type StatusCode = number;

/**
* Interface describing `dlagts`.
*/
interface Routine {
	/**
	* Solves a system of equations with a tridiagonal matrix `T` following a precomputed factorization of `T - lambda*I`.
	*
	* @param job - specifies the job to be performed
	* @param N - order of the matrix `T`
	* @param A - diagonal elements of `U`
	* @param B - first super-diagonal elements of `U`
	* @param C - sub-diagonal elements of `L`
	* @param D - second super-diagonal elements of `U`
	* @param IN - details of the matrix `P`
	* @param Y - right-hand side vector which is overwritten by the solution vector
	* @param TOL - tolerance used to perturb very small diagonal elements when `job` is negative
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 4.0, 3.75, 3.7333333333333334 ] );
	* var B = new Float64Array( [ 1.0, 1.0 ] );
	* var C = new Float64Array( [ 0.25, 0.26666666666666666 ] );
	* var D = new Float64Array( [ 0.0 ] );
	* var IN = new Int32Array( [ 0, 0, 0 ] );
	* var Y = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	* var TOL = new Float64Array( [ 0.0 ] );
	*
	* dlagts( 1, 3, A, B, C, D, IN, Y, TOL );
	* // Y => <Float64Array>[ ~0.179, ~0.286, ~0.679 ]
	*/
	( job: number, N: number, A: Float64Array, B: Float64Array, C: Float64Array, D: Float64Array, IN: Int32Array, Y: Float64Array, TOL: Float64Array ): StatusCode;

	/**
	* Solves a system of equations with a tridiagonal matrix `T` following a precomputed factorization of `T - lambda*I` using alternative indexing semantics.
	*
	* @param job - specifies the job to be performed
	* @param N - order of the matrix `T`
	* @param A - diagonal elements of `U`
	* @param strideA - stride length for `A`
	* @param offsetA - starting index for `A`
	* @param B - first super-diagonal elements of `U`
	* @param strideB - stride length for `B`
	* @param offsetB - starting index for `B`
	* @param C - sub-diagonal elements of `L`
	* @param strideC - stride length for `C`
	* @param offsetC - starting index for `C`
	* @param D - second super-diagonal elements of `U`
	* @param strideD - stride length for `D`
	* @param offsetD - starting index for `D`
	* @param IN - details of the matrix `P`
	* @param strideIN - stride length for `IN`
	* @param offsetIN - starting index for `IN`
	* @param Y - right-hand side vector which is overwritten by the solution vector
	* @param strideY - stride length for `Y`
	* @param offsetY - starting index for `Y`
	* @param TOL - tolerance used to perturb very small diagonal elements when `job` is negative
	* @param offsetTOL - index for `TOL`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 4.0, 3.75, 3.7333333333333334 ] );
	* var B = new Float64Array( [ 1.0, 1.0 ] );
	* var C = new Float64Array( [ 0.25, 0.26666666666666666 ] );
	* var D = new Float64Array( [ 0.0 ] );
	* var IN = new Int32Array( [ 0, 0, 0 ] );
	* var Y = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	* var TOL = new Float64Array( [ 0.0 ] );
	*
	* dlagts.ndarray( 1, 3, A, 1, 0, B, 1, 0, C, 1, 0, D, 1, 0, IN, 1, 0, Y, 1, 0, TOL, 0 );
	* // Y => <Float64Array>[ ~0.179, ~0.286, ~0.679 ]
	*/
	ndarray( job: number, N: number, A: Float64Array, strideA: number, offsetA: number, B: Float64Array, strideB: number, offsetB: number, C: Float64Array, strideC: number, offsetC: number, D: Float64Array, strideD: number, offsetD: number, IN: Int32Array, strideIN: number, offsetIN: number, Y: Float64Array, strideY: number, offsetY: number, TOL: Float64Array, offsetTOL: number ): StatusCode;
}

/**
* Solves a system of equations with a tridiagonal matrix `T` following a precomputed factorization of `T - lambda*I`.
*
* @param job - specifies the job to be performed
* @param N - order of the matrix `T`
* @param A - diagonal elements of `U`
* @param B - first super-diagonal elements of `U`
* @param C - sub-diagonal elements of `L`
* @param D - second super-diagonal elements of `U`
* @param IN - details of the matrix `P`
* @param Y - right-hand side vector which is overwritten by the solution vector
* @param TOL - tolerance used to perturb very small diagonal elements when `job` is negative
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 4.0, 3.75, 3.7333333333333334 ] );
* var B = new Float64Array( [ 1.0, 1.0 ] );
* var C = new Float64Array( [ 0.25, 0.26666666666666666 ] );
* var D = new Float64Array( [ 0.0 ] );
* var IN = new Int32Array( [ 0, 0, 0 ] );
* var Y = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var TOL = new Float64Array( [ 0.0 ] );
*
* dlagts( 1, 3, A, B, C, D, IN, Y, TOL );
* // Y => <Float64Array>[ ~0.179, ~0.286, ~0.679 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 4.0, 3.75, 3.7333333333333334 ] );
* var B = new Float64Array( [ 1.0, 1.0 ] );
* var C = new Float64Array( [ 0.25, 0.26666666666666666 ] );
* var D = new Float64Array( [ 0.0 ] );
* var IN = new Int32Array( [ 0, 0, 0 ] );
* var Y = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var TOL = new Float64Array( [ 0.0 ] );
*
* dlagts.ndarray( 1, 3, A, 1, 0, B, 1, 0, C, 1, 0, D, 1, 0, IN, 1, 0, Y, 1, 0, TOL, 0 );
* // Y => <Float64Array>[ ~0.179, ~0.286, ~0.679 ]
*/
declare var dlagts: Routine;


// EXPORTS //

export = dlagts;
